// Type-R 198X — DRONES (presentation pass 2026-11): every word plate gets a body.
//
// A plate is the call-sign tag of a small drone that flies a dozen pixels behind it (to the right, the way the
// stream comes from), tethered by a hairline in the sector accent. Four classes keyed by what the plate carries
// (scout: single letters, interceptor: 2-4 letters, hauler: 5+, pod: boss minions), three silhouettes each and two
// animation frames (engine flicker / nav blink) on one sheet generated by tools/art/gen_drones.py. The sheet has a
// HULL band (neutral steel, white engine cores) over an ACCENT band (alpha = where the sector colour goes): at
// sector start dronesBake() composites hull + tinted accent into one canvas for the sector accent and one in
// magenta for the minion pods (three composite sets at bake time, none per frame).
//
// Drawing: drawEnemies / drawAttract are wrapped so every drone of the frame is drawn BEFORE any plate (a drone must
// never sit over a neighbour's text), source-over only: one drawImage, one tether line, lime corner brackets while
// the plate is locked. The engine core is white and the glow accent-bright, so the bloom pass (76-bloom.js) lights
// it. Idle: a 2.5 px bob, a +-.05 rad roll and a 9 Hz frame flicker, all phase-offset per drone; reduce-motion keeps
// the body still and fades it in.
//
// Lifecycle: the drone is derived state (en._drone), so nothing in combat changes. dronesTick (tick hook) compares
// the enemies drawn last frame with the live list: a plate that was killed leaves a WRECK that tumbles for .22 s
// and pops (small explosion sprite + debris + sparks), a plate that leaked streaks past the ship and fades. Ghost
// plates of the attract mode get drones too (no wrecks: they dissolve).
//
// Loader: key "fx/drones" (assets/opt/fx/drones.webp, lossless; fallback assets/sprites/drones.png), pinned and
// critical (12 KB). Cells are laid out by formula (see droneCell), so a regenerated sheet with the same class
// sizes needs no table edit; the sizes below mirror drones.json.

const DRONES = Object.freeze({
  key: "fx/drones",
  sheet: Object.freeze({ w: 1152, h: 896, cellW: 192, cellH: 112, cols: 6, bandH: 448, frames: 2, variants: 3 }),
  classes: Object.freeze({
    scout: Object.freeze({ w: 96, h: 56 }),
    interceptor: Object.freeze({ w: 136, h: 64 }),
    hauler: Object.freeze({ w: 176, h: 88 }),
    pod: Object.freeze({ w: 88, h: 88 })
  }),
  order: Object.freeze(["scout", "interceptor", "hauler", "pod"]),
  drawScale: 0.5,          // logical px per sheet px (2 logical px per art pixel, like the ships)
  gap: 12,                 // plate right edge -> drone nose, logical px
  bobPx: 2.5,
  bobHz: 1.1,
  rollRad: 0.05,
  flickerHz: 9,
  fadeInS: 0.28,           // the body condenses out of the spawn streak
  tetherA: 0.40,
  bracketA: 0.85,
  wreck: Object.freeze({ life: 0.22, spin: 9, gravity: 420, vx: -60, vy: -50, leakLife: 0.45, leakSpeedMul: 1.6, cap: 24 })
});

function droneClassFor(en) {
  if (!en) return "scout";
  if (en.kind === "bossMinion") return "pod";
  const n = en.text ? en.text.length : 1;
  return n <= 1 ? "scout" : n <= 4 ? "interceptor" : "hauler";
}

function droneHash(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h >>> 0;
}

// Cell rect in sheet pixels (hull band; the accent band sits DRONES.sheet.bandH lower).
function droneCell(cls, v, f) {
  const S = DRONES.sheet;
  const c = DRONES.classes[cls] || DRONES.classes.scout;
  const i = DRONES.order.indexOf(cls) * S.variants * S.frames + v * S.frames + f;
  const col = i % S.cols, row = (i / S.cols) | 0;
  return { x: col * S.cellW + ((S.cellW - c.w) >> 1), y: row * S.cellH + ((S.cellH - c.h) >> 1), w: c.w, h: c.h };
}

Object.assign(Game.prototype, {
  droneOf(en) {
    let d = en._drone;
    if (!d) {
      const cls = droneClassFor(en);
      const h = droneHash(String(en.text || "") + (en.lane | 0));
      d = en._drone = { cls, v: h % DRONES.sheet.variants, phase: (h % 628) / 100, lastX: NaN, lastY: NaN, wrecked: false };
    }
    return d;
  },

  droneState() {
    return this._drones || (this._drones = { bake: null, tracked: [], wrecks: [], frameTracked: 0 });
  },

  // Hull + tinted accent for the current sector accent (and magenta for pods). Rebuilt when the drawable (DPR flip
  // re-prepare) or the accent changes. Returns null while the sheet is not resident.
  dronesBake() {
    const sheet = (typeof Assets !== "undefined" && Assets && typeof Assets.get === "function") ? Assets.get(DRONES.key) : null;
    if (!sheet || !(sheet.width > 0)) return null;
    if (typeof sheet.complete === "boolean" && !sheet.complete) return null;
    const st = this.droneState();
    const accent = PALETTE.rgba("accent", 1);
    const hit = st.bake;
    if (hit && hit.src === sheet && hit.accent === accent) return hit;
    const k = sheet.width / DRONES.sheet.w;
    const bw = sheet.width, bh = Math.round(DRONES.sheet.bandH * k);
    const make = (tint) => {
      const canvas = document.createElement("canvas");
      canvas.width = bw; canvas.height = bh;
      const g = canvas.getContext("2d");
      g.imageSmoothingEnabled = false;
      g.drawImage(sheet, 0, 0, bw, bh, 0, 0, bw, bh);
      const tmp = document.createElement("canvas");
      tmp.width = bw; tmp.height = bh;
      const t = tmp.getContext("2d");
      t.imageSmoothingEnabled = false;
      t.drawImage(sheet, 0, bh, bw, bh, 0, 0, bw, bh);
      t.globalCompositeOperation = "source-in";
      t.fillStyle = tint;
      t.fillRect(0, 0, bw, bh);
      g.drawImage(tmp, 0, 0);
      tmp.width = 0;
      return canvas;
    };
    let main, minion;
    try { main = make(accent); minion = make(PALETTE.rgba("magenta", 1)); } catch (_) { return null; }
    if (hit) { hit.main.width = 0; hit.minion.width = 0; }
    st.bake = { src: sheet, accent, k, main, minion };
    return st.bake;
  },

  // Geometry shared by the draw and the wreck hand-off: centre, size and the animation pose for this frame.
  dronePose(en) {
    const d = this.droneOf(en);
    const c = DRONES.classes[d.cls];
    const lw = c.w * DRONES.drawScale, lh = c.h * DRONES.drawScale;
    const t = this.starT || 0;
    const m = typeof this.motion === "function" ? this.motion() : { anim: 1 };
    const anim = m.anim > 0;
    const bob = anim ? Math.sin(t * Math.PI * 2 * DRONES.bobHz + d.phase) * DRONES.bobPx : 0;
    const roll = anim ? Math.sin(t * Math.PI * 2 * 0.7 + d.phase * 1.3) * DRONES.rollRad : 0;
    const frame = anim ? (((t * DRONES.flickerHz + d.phase) | 0) & 1) : 0;
    const plateW = en.plateW || 40;
    const cx = en.x + plateW / 2 + DRONES.gap + lw / 2;
    const cy = en.y + bob;
    return { d, c, lw, lh, cx, cy, roll, frame, plateW };
  },

  // Every drone of `list` (already sorted far to near by the caller), then the caller draws the plates over them.
  drawDrones(ctx, list, alphaMul = 1, track = true) {
    if (!list || !list.length) return;
    if (typeof window !== "undefined" && window.TypeRHarness && window.TypeRHarness.drones === false) return;   // pixel probes freeze the bodies
    const bake = this.dronesBake();
    if (!bake) return;
    const st = this.droneState();
    if (track && st.frameTracked !== this.frameCount) { st.tracked.length = 0; st.frameTracked = this.frameCount; }
    const W = this.w;
    const lime = PALETTE.rgba("lime", DRONES.bracketA);
    for (const en of list) {
      if (!en || en.alive === false) continue;
      const p = this.dronePose(en);
      const d = p.d;
      d.lastX = p.cx; d.lastY = p.cy;
      if (track) st.tracked.push(en);
      const ghostFade = (en.dying && typeof en.attractFade === "number") ? clamp(1 - en.attractFade, 0, 1) : 1;   // attract ghosts dissolve past fadeX
      const fade = clamp((en.age || 0) / DRONES.fadeInS, 0, 1) * alphaMul * ghostFade;
      if (fade <= 0.02 || p.cx - p.lw / 2 > W + 4) continue;
      const minion = en.kind === "bossMinion";
      const cell = droneCell(d.cls, d.v, p.frame);
      const k = bake.k;
      ctx.save();
      ctx.globalAlpha *= fade;
      // tether: plate edge -> nose
      ctx.strokeStyle = PALETTE.rgba(minion ? "magenta" : "accent", DRONES.tetherA);
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(Math.round(en.x + p.plateW / 2) + 1, Math.round(en.y) + 0.5);
      ctx.lineTo(Math.round(p.cx - p.lw / 2) + 3, Math.round(p.cy) + 0.5);
      ctx.stroke();
      ctx.translate(Math.round(p.cx), Math.round(p.cy));
      if (p.roll) ctx.rotate(p.roll);
      ctx.drawImage(minion ? bake.minion : bake.main, cell.x * k, cell.y * k, cell.w * k, cell.h * k, -p.lw / 2, -p.lh / 2, p.lw, p.lh);
      if (en.locked) {
        const hw = p.lw / 2 + 5, hh = p.lh / 2 + 5, L = 6;
        ctx.strokeStyle = lime;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(-hw, -hh + L); ctx.lineTo(-hw, -hh); ctx.lineTo(-hw + L, -hh);
        ctx.moveTo(hw - L, -hh); ctx.lineTo(hw, -hh); ctx.lineTo(hw, -hh + L);
        ctx.moveTo(hw, hh - L); ctx.lineTo(hw, hh); ctx.lineTo(hw - L, hh);
        ctx.moveTo(-hw + L, hh); ctx.lineTo(-hw, hh); ctx.lineTo(-hw, hh - L);
        ctx.stroke();
      }
      ctx.restore();
    }
    this.drawDroneWrecks(ctx, bake);
  },

  drawDroneWrecks(ctx, bake) {
    const st = this.droneState();
    if (!st.wrecks.length) return;
    for (const w of st.wrecks) {
      const cell = droneCell(w.cls, w.v, w.frame);
      const k = bake.k;
      const u = clamp(w.t / w.life, 0, 1);
      ctx.save();
      ctx.globalAlpha *= w.kind === "leak" ? (1 - u) : 1;
      ctx.translate(Math.round(w.x), Math.round(w.y));
      ctx.rotate(w.rot);
      ctx.drawImage(w.minion ? bake.minion : bake.main, cell.x * k, cell.y * k, cell.w * k, cell.h * k, -w.lw / 2, -w.lh / 2, w.lw, w.lh);
      ctx.restore();
    }
  },

  // Hand a vanished plate's drone over to the wreck list (once).
  droneWreck(en, live) {
    const d = en._drone;
    if (!d || d.wrecked || !Number.isFinite(d.lastX)) return;
    d.wrecked = true;
    const st = this.droneState();
    if (st.wrecks.length >= DRONES.wreck.cap) st.wrecks.shift();
    if (d.lastX > this.w + 20) return;                        // died off-screen: nothing to show
    const c = DRONES.classes[d.cls];
    const rm = !!this.reduceMotion;
    const nearShip = en.x < (this.player ? this.player.x + 80 : 200);
    const leak = nearShip && !this.bossClear;
    const W = DRONES.wreck;
    st.wrecks.push({
      kind: leak ? "leak" : "kill", cls: d.cls, v: d.v, frame: 0, minion: en.kind === "bossMinion",
      x: d.lastX, y: d.lastY, lw: c.w * DRONES.drawScale, lh: c.h * DRONES.drawScale,
      vx: leak ? -(en.speed || 120) * W.leakSpeedMul : (rm ? 0 : W.vx), vy: leak ? 0 : (rm ? 0 : W.vy),
      rot: 0, spin: (leak || rm) ? 0 : (Math.random() < 0.5 ? -W.spin : W.spin),
      t: 0, life: leak ? W.leakLife : (rm ? 0.08 : W.life)
    });
  },

  dronesTick(dt) {
    const st = this._drones;
    if (!st) return;
    if (st.tracked.length) {
      const live = new Set(this.enemies);
      const ghosts = this.attract && this.attract.ghosts;
      if (ghosts) for (const g of ghosts) live.add(g);
      for (const en of st.tracked) {
        if (!en) continue;
        const gone = en.alive === false || !live.has(en);
        if (gone && !(en._drone && en._drone.wrecked)) {
          // attract ghosts dissolve past fadeX without a leak: no wreck for them
          if (ghosts && ghosts.includes(en)) { if (en._drone) en._drone.wrecked = true; continue; }
          if (en.alive === false && this.attract && this.mode === "menu") { if (en._drone) en._drone.wrecked = true; continue; }
          this.droneWreck(en, live);
        }
      }
      st.tracked.length = 0;
    }
    if (!st.wrecks.length) return;
    const W = DRONES.wreck;
    compactInPlace(st.wrecks, (w) => {
      w.t += dt;
      w.x += w.vx * dt;
      w.y += w.vy * dt;
      if (w.kind === "kill") w.vy += W.gravity * dt;
      w.rot += w.spin * dt;
      if (w.t < w.life) return true;
      if (w.kind === "kill") {
        if (typeof this.addExplosionSprite === "function") this.addExplosionSprite(w.x, w.y, "small");
        if (typeof this.addDebris === "function") this.addDebris(w.x, w.y, w.cls === "hauler" ? 4 : 2);
        if (typeof this.addSparks === "function") this.addSparks(w.x, w.y, 6);
      }
      return false;
    });
  },

  dronesReset() {
    const st = this._drones;
    if (!st) return;
    st.tracked.length = 0;
    st.wrecks.length = 0;
  }
});

// Drones under the plates: both plate passes get a drone pre-pass over the same far-to-near order.
(function wrapDroneDraws() {
  const drawEnemies = Game.prototype.drawEnemies;
  Game.prototype.drawEnemies = function (ctx) {
    const list = this.enemies;
    if (list && list.length) this.drawDrones(ctx, list.slice().sort((a, b) => b.x - a.x), 1, true);
    return drawEnemies.call(this, ctx);
  };
  const drawAttract = Game.prototype.drawAttract;
  if (typeof drawAttract === "function") {
    Game.prototype.drawAttract = function (ctx) {
      const a = this.attract;
      const ghosts = a && a.ghosts;
      if (ghosts && ghosts.length) {
        const alpha = (typeof ATTRACT === "object" && ATTRACT && typeof ATTRACT.alpha === "number") ? ATTRACT.alpha : 0.85;
        this.drawDrones(ctx, ghosts.slice().sort((x, y) => y.x - x.x), alpha, true);
      }
      return drawAttract.call(this, ctx);
    };
  }
})();

onGameHook("sectorStart", function () { if (typeof this.dronesReset === "function") this.dronesReset(); if (typeof this.dronesBake === "function") this.dronesBake(); });
onGameHook("tick", function (ev) { if (typeof this.dronesTick === "function") this.dronesTick(ev && typeof ev.dt === "number" ? ev.dt : 0); });
